/* Explicit demonstration model: Ts=10 us, L=100 uH, C=100 uF, R=5 ohm.
   The horizon holds each candidate duty constant for eight predicted samples.
   Re-identify these constants if the power stage changes. */
const double Ts=1e-5, L=100e-6, C=100e-6, R=5.0, Vf=0.55, Ron=0.01;
double best=1e100;
duty=0.02;
for (int candidate=2; candidate<=95; ++candidate) {
    double d=0.01*candidate, ip=current, vp=voltage;
    double cost=0.001*(d-previous)*(d-previous);
    for (int k=0; k<8; ++k) {
        double next_i=ip+Ts*(d*(supply-Ron*ip)-(1.0-d)*Vf-vp)/L;
        double next_v=vp+Ts*(ip-vp/R)/C;
        ip=next_i; vp=next_v;
        double ev=vp-reference, ei=ip-reference/R;
        cost += ev*ev + 0.02*ei*ei;
        if (ip<0 || ip>6) cost += 100.0;
    }
    if (cost<best) { best=cost; duty=d; }
}
next_previous=duty;
